import {DIFFICULTIES} from './game.mjs';
import {formatLap,signed,sampleAtTime,clamp} from './engine.mjs';
import {ROOM_ENDPOINT,ROOM_PUBLIC_KEY} from './rooms-config.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const randomToken=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
const storageKey='laplab-room-session-v1';
export function initCompetition({db,toast}){
 let connection,room,offset=0,timer,animation,uiKey='',busy=false,pendingCreate,pendingJoin,failures=0,map=[],lastFinish='',lastVersion=-1,lastReadoutAt=0;
 const host=$('#compete-view');
 host.innerHTML=`<div class="duel-intro"><div><p class="eyebrow">LAPLAB / SETUP DUEL</p><h2>Same brief.<br>Two approaches.</h2><p>Invite a friend. Tune the car. Watch the answer unfold.</p></div><div class="duel-format"><b>2</b><span>PLAYERS</span><b>5</b><span>ROUNDS</span><b>1×</b><span>REAL-TIME REPLAY</span></div></div><div id="room-alert" class="experiment-status" role="status" aria-live="polite"></div><div id="room-landing" class="room-landing"><form id="room-create-form" class="panel room-create"><p class="eyebrow">CREATE A PRIVATE MATCH</p><h3>Your garage. Your invitation.</h3><label class="lab-input" for="room-name"><span>Display name</span><input id="room-name" minlength="2" maxlength="24" required autocomplete="nickname" placeholder="Your name"></label><label class="lab-input" for="room-difficulty"><span>Difficulty</span><select id="room-difficulty">${Object.entries(DIFFICULTIES).map(([key,v])=>`<option value="${key}" ${key==='engineer'?'selected':''}>${v.name}</option>`).join('')}</select></label><p id="difficulty-description" class="small-note"></p><button class="button primary" type="submit" id="room-create">Create friend room ↗</button><p class="small-note">No account required. Room access stays in this tab and survives refresh. Rooms expire after 24 hours.</p></form><form class="panel room-join" id="room-join-form"><p class="eyebrow">GOT AN INVITATION?</p><h3>Take the other side.</h3><label class="lab-input" for="join-link"><span>Invitation link</span><input id="join-link" type="url" required placeholder="Paste your friend’s invitation"></label><label class="lab-input" for="join-name"><span>Your display name</span><input id="join-name" minlength="2" maxlength="24" required autocomplete="nickname"></label><button class="button quiet" id="room-join" type="submit">Join friend room ↗</button><p class="small-note">Each round fixes the driver, chassis, tyres, fuel and weather. Only the listed setup variables can change.</p></form></div><div id="room-shell" hidden><div class="room-topline"><span id="room-connection">Connecting…</span><button class="text-button" id="room-leave">Leave this tab’s room ↗</button></div><div class="match-score" id="match-score"></div><div class="round-progress" id="round-progress"></div><div id="room-content"></div></div><details class="panel duel-rules"><summary>Read the five-round rules</summary><ol><li>Both players receive the same five briefs, including a 1 MJ conservation round. Weather and vehicle identity are fixed; setup choices remain private while tuning.</li><li>Guided: wing and bias, 100 tests per round. Engineer: wing, bias and ERS, eight tests. Expert: three tests and a tighter setup budget. This is a casual challenge; the public solver can also be studied outside the room.</li><li>Setup budget = |aero trim| + |front bias − 56| / 3. This is a game constraint, not an FIA regulation or a measured garage resource.</li><li>Locking is final for the round. After both setups lock, a five-second shared countdown starts two independent flying laps at actual simulated speed. No random penalties or collisions.</li><li>The first car to finish wins one point. Times within 0.005 s share the point. All five rounds are played. Most round points wins; total lap time breaks a points tie, otherwise it is a shared win.</li><li>Both players choose “Ready for next round” after the replay. A disconnected player can reconnect in the same tab. This MVP has no replacement players, wagers, public rankings or model-accuracy claims.</li></ol></details>`;
 const alert=(text,error=false)=>{$('#room-alert').textContent=text;$('#room-alert').classList.toggle('lab-error',error);};
 function persist(){try{sessionStorage.setItem(storageKey,JSON.stringify(connection));}catch{alert('Tab storage is unavailable. Keep this page open; refreshing will lose player access.',true);}}
 async function request(action,extra={}){
  if(!ROOM_ENDPOINT)throw Error('Live rooms are not configured on this deployment yet. The local simulation and experiments remain available.');
  const start=Date.now(),response=await fetch(ROOM_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json',...(ROOM_PUBLIC_KEY?{apikey:ROOM_PUBLIC_KEY}:{})},body:JSON.stringify({action,...connection,knownVersion:lastVersion,hasRace:!!room?.race,...extra}),signal:AbortSignal.timeout(15000),cache:'no-store'});
  let data;try{data=await response.json();}catch{throw Error('The room service returned an unreadable response. Retry to reconnect.');}
  if(!response.ok){const e=Error(data.error||'Room request failed.');e.status=response.status;throw e;}
  if(!data.brief||!Array.isArray(data.players)||!Number.isFinite(data.serverNow))throw Error('The room response is incomplete. Retry to reconnect.');
  if(data.version<lastVersion)return room;
  if(data.id===room?.id&&data.round===room?.round&&data.startAt&&!data.race)data.race=room.race;
  lastVersion=data.version;offset=data.serverNow+(Date.now()-start)/2-Date.now();room=data;failures=0;alert('');renderRoom();return data;
 }
 async function act(action,extra){
  if(busy)return;busy=true;host.querySelectorAll('button[type="submit"],#duel-test,#duel-lock,#duel-next').forEach(b=>b.disabled=true);
  try{await request(action,extra);}catch(e){alert(e.message,true);}finally{busy=false;renderRoom();host.querySelectorAll('#room-create,#room-join').forEach(b=>b.disabled=false);}
 }
 function schedule(){clearTimeout(timer);timer=setTimeout(async()=>{if(!connection)return;try{await request('status');}catch(e){failures++;$('#room-connection').textContent='Reconnecting · inputs preserved';alert(e.status===404||e.status===410?e.message:'Connection interrupted. We are reconnecting; locked setups stay on the server.',true);}finally{schedule();}},document.hidden||host.hidden?5000:Math.min(10000,1500*(1+failures)));}
 $('#room-difficulty').onchange=()=>$('#difficulty-description').textContent=DIFFICULTIES[$('#room-difficulty').value].description;$('#room-difficulty').onchange();
 $('#room-create-form').onsubmit=async e=>{
  e.preventDefault();if(busy)return;
  pendingCreate??={roomId:crypto.randomUUID(),token:randomToken()};connection=pendingCreate;lastVersion=-1;uiKey='';
  await act('create',{name:$('#room-name').value,difficulty:$('#room-difficulty').value});if(room){persist();pendingCreate=null;schedule();}
 };
 $('#room-join-form').onsubmit=async e=>{
  e.preventDefault();if(busy)return;
  try{const url=new URL($('#join-link').value);if(!['https://f1-laplab.vercel.app','https://f1-laplab-deadpoods.vercel.app',location.origin].includes(url.origin)||!url.searchParams.get('room')||!url.searchParams.get('invite'))throw Error('Paste a complete LapLab friend invitation.');const roomId=url.searchParams.get('room'),invite=url.searchParams.get('invite');if(pendingJoin?.roomId!==roomId||pendingJoin.invite!==invite)pendingJoin={roomId,invite,token:randomToken()};connection={roomId,token:pendingJoin.token};lastVersion=-1;uiKey='';await act('join',{invite,name:$('#join-name').value});if(room){persist();pendingJoin=null;schedule();}}catch(error){alert(error.message,true);}
 };
 $('#room-leave').onclick=()=>{clearTimeout(timer);cancelAnimationFrame(animation);connection=null;room=null;lastVersion=-1;uiKey='';host.dataset.roomActive='false';try{sessionStorage.removeItem(storageKey);}catch{}const url=new URL(location.href);url.searchParams.delete('room');url.searchParams.delete('invite');history.replaceState(null,'',url);$('#room-shell').hidden=true;$('#room-landing').hidden=false;alert('You left this tab’s room. The shared match remains until it expires.');};
 function settings(){const brief=room.brief,value={wing:Number($('#duel-wing').value),brakeBias:Number($('#duel-bias').value)};if(brief.allowed.includes('ers'))value.ers=$('#duel-ers').value;return value;}
 function phase(){if(room.score.complete)return 'finished';if(room.result)return 'rounddone';if(room.startAt)return Date.now()+offset<room.startAt?'countdown':'racing';return room.players.length===2?'tuning':'waiting';}
 function renderRoom(){
  if(!room)return;host.dataset.roomActive='true';$('#room-landing').hidden=true;$('#room-shell').hidden=false;$('#room-connection').textContent='● Connected · shared room';
  const currentPhase=phase(),key=`${room.id}:${room.round}:${currentPhase}`,r=room.brief;
  $('#match-score').innerHTML=room.players.map((p,i)=>`<div class="player-score player-${i}"><span>${esc(p.name)}${i===room.me?' / YOU':''}</span><b>${room.score.scores[i]}</b><small>${p.locked?'SETUP LOCKED':'IN THE GARAGE'}</small></div>`).join('')+(room.players.length<2?'<div class="player-score player-1"><span>YOUR FRIEND</span><b>—</b><small>AWAITING INVITATION</small></div>':'');
  $('#round-progress').innerHTML=Array.from({length:5},(_,i)=>{const h=room.history.find(x=>x.round===i);return `<span class="${i===room.round?'current':''}"><b>0${i+1}</b>${h?h.tie?'TIE':esc(room.players[h.winner].name):i===room.round?'CURRENT':'UP NEXT'}</span>`;}).join('');
  if(key!==uiKey){uiKey=key;cancelAnimationFrame(animation);
   if(currentPhase==='waiting'){
    const url=new URL(location.origin+'/');url.searchParams.set('room',room.id);url.searchParams.set('invite',room.invite);url.hash='compete';
    $('#room-content').innerHTML=`<div class="panel waiting-room"><p class="eyebrow">${DIFFICULTIES[room.difficulty].name.toUpperCase()} / PRIVATE MATCH</p><h3>The other garage is waiting.</h3><p>Share this link with one friend. Once they join, the first brief opens for both of you.</p><label class="lab-input" for="room-invite"><span>Invitation · expires in 24 hours</span><input id="room-invite" readonly value="${esc(url.href)}"></label><button id="room-copy" class="button primary">Copy invitation ↗</button><p class="small-note">Player access is stored in this tab. Keep it open throughout the match.</p></div>`;$('#room-copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Friend invitation copied.');}catch{$('#room-invite').select();toast('Select and copy the invitation link.');}};
   }else if(currentPhase==='tuning'){
    $('#room-content').innerHTML=`<div class="duel-garage"><section class="panel duel-brief"><p class="eyebrow">ROUND 0${room.round+1} / ${db.circuits.find(c=>c.id===r.circuit).name.toUpperCase()}</p><h3>${r.title}</h3><p>${r.brief}</p><dl><div><dt>Vehicle / driver</dt><dd>MCL38 / NOR</dd></div><div><dt>Tyres / fuel</dt><dd>Fresh soft / ${r.fuel} kg</dd></div><div><dt>Track / wind</dt><dd>${r.baseline.trackTemp} °C / ${r.wind} km/h at ${r.windDirection}°</dd></div><div><dt>Setup budget</dt><dd>${r.budget} units</dd></div>${r.energyLimit?`<div><dt>ES deployment limit</dt><dd>${r.energyLimit} MJ</dd></div>`:''}</dl><p class="small-note">Qualifying, dry, clean air. Direction is relative to the finish straight. Model assumptions apply to all game rounds.</p><div id="opponent-state" class="opponent-state"></div></section><form id="duel-setup" class="panel duel-controls"><p class="eyebrow">YOUR PRIVATE SETUP</p><h3>Find your compromise.</h3><label class="lab-input" for="duel-wing"><span>Aero trim · integer level</span><input id="duel-wing" type="number" min="-2" max="2" step="1" value="0" required></label><label class="lab-input" for="duel-bias"><span>Front brake bias · %</span><input id="duel-bias" type="number" min="50" max="65" step="${r.biasStep}" value="56" required></label>${r.allowed.includes('ers')?`<label class="lab-input" for="duel-ers"><span>ERS deployment</span><select id="duel-ers"><option value="balanced">Balanced</option><option value="attack">Attack</option><option value="harvest">Conserve</option></select></label>`:''}<div id="duel-budget" class="setup-budget"></div><p id="duel-test-count" class="small-note"></p><div class="duel-actions"><button id="duel-test" class="button quiet" type="button">Test this setup</button><button id="duel-lock" class="button primary" type="submit">Lock setup & ready ↗</button></div><div id="duel-test-result" class="duel-test-result"></div><p class="small-note">Locking is final. Neither lap result is shown during the race until the car crosses the finish.</p></form></div>`;
    if($('#duel-ers'))$('#duel-ers').value=r.baseline.ers;
    $('#duel-test').onclick=()=>act('test',{round:room.round,settings:settings(),actionId:crypto.randomUUID()});$('#duel-setup').onsubmit=e=>{e.preventDefault();act('lock',{round:room.round,settings:settings()});};
    const updateBudget=()=>{const value=Math.abs(Number($('#duel-wing').value))+Math.abs(Number($('#duel-bias').value)-56)/3;$('#duel-budget').textContent=`SETUP BUDGET / ${value.toFixed(2)} of ${r.budget} · |trim| + |bias − 56| / 3`;$('#duel-budget').classList.toggle('lab-error',value>r.budget);};$('#duel-wing').oninput=updateBudget;$('#duel-bias').oninput=updateBudget;updateBudget();
   }else if(currentPhase==='countdown'||currentPhase==='racing'){
    $('#room-content').innerHTML=`<section class="panel duel-stage"><div class="duel-stage-heading"><div><p class="eyebrow">ROUND 0${room.round+1} / TWO INDEPENDENT FLYING LAPS</p><h3>${r.title}</h3></div><div id="race-clock">00:00.00</div></div><div class="duel-track"><svg id="duel-track-svg" viewBox="0 0 900 500" role="img" aria-label="Two simulated cars racing on ${db.circuits.find(c=>c.id===r.circuit).name}"><g id="duel-road"></g><g id="duel-car-0" class="duel-car player-0"><circle r="13" class="car-halo"/><path d="M-13-4H6L15 0 6 4H-13ZM-9-8h4v16h-4M8-9h3v18H8"/></g><g id="duel-car-1" class="duel-car player-1"><circle r="13" class="car-halo"/><path d="M-13-4H6L15 0 6 4H-13ZM-9-8h4v16h-4M8-9h3v18H8"/></g></svg><div id="race-countdown" class="race-countdown"></div><div id="race-announcement" class="race-announcement" role="status" aria-live="polite" hidden></div></div><div id="race-telemetry" class="race-telemetry"></div><p class="table-note">1× simulated time · shared server start · cars use their own computed s(t). Small lateral offsets make both cars visible; contact and overtaking dynamics are omitted.</p></section>`;drawTrack();animate();
   }else{
    const finish=currentPhase==='finished',win=finish?room.score.winner:room.finish.winner,tie=finish?room.score.tie:room.finish.tie;
    const title=tie?finish?'A shared victory.':'A dead heat.':`${room.players[win].name} ${finish?'wins the match.':'takes the round.'}`;
    $('#room-content').innerHTML=`<section class="panel duel-result"><p class="eyebrow">${finish?'FIVE ROUNDS / MATCH COMPLETE':`ROUND 0${room.round+1} / BOTH CARS HOME`}</p><h3>${esc(title)}</h3><div class="result-podium">${room.result.times.map((t,i)=>`<div class="player-${i}"><span>${esc(room.players[i].name)}</span><b>${formatLap(t)}</b><small>Trim ${room.result.settings[i].wing??0} / bias ${room.result.settings[i].brakeBias??56}% / ${room.result.settings[i].ers||r.baseline.ers}</small></div>`).join('')}</div><div class="duel-analysis"><p>${esc(room.result.analysis.explanation.replace('Scenario A',room.players[0].name))}</p><p>${esc(room.result.analysis.mechanism||'Both setups produce the same modelled lap.')}</p><div class="sweep-sectors">${room.result.analysis.sectorDeltas.map((d,i)=>`<span>S${i+1}<b>${signed(d)} s</b></span>`).join('')}</div><p class="small-note">Sector deltas are player 1 minus player 2. Model differences identify the winning setup within this simulation; they do not establish real-world superiority.</p></div>${finish?`<p>Final points: ${room.score.scores.join(' : ')}. Total flying time: ${room.score.totals.map(formatLap).join(' / ')}.</p><button class="button primary" id="duel-new">Create another match ↗</button>`:'<button class="button primary" id="duel-next">Ready for next round ↗</button><p id="next-ready-state" class="small-note"></p>'}</section>`;
    if(finish)$('#duel-new').onclick=()=>$('#room-leave').click();else $('#duel-next').onclick=()=>act('next',{round:room.round});
   }
  }
  if(currentPhase==='tuning'){
   const locked=room.players[room.me].locked;$('#opponent-state').textContent=room.players[1-room.me].locked?'Your friend is locked and ready. Their setup remains private.':'Your friend is still tuning.';
   $('#duel-test-count').textContent=`${r.tests-room.tests.length} / ${r.tests} private tests remain.`;$('#duel-test').disabled=busy||locked||room.tests.length>=r.tests;$('#duel-lock').disabled=busy||locked;
   ['#duel-wing','#duel-bias','#duel-ers'].forEach(selector=>{const el=$(selector);if(el)el.disabled=locked||busy;});
   if(locked)$('#duel-test-result').textContent='Setup locked. Waiting for your friend to lock.';
   else if(room.tests.length){const t=room.tests.at(-1);$('#duel-test-result').innerHTML=`<span>LAST PRIVATE TEST</span><b>${formatLap(t.lapTime)}</b><small>Sectors ${t.sectors.map(x=>x.toFixed(2)).join(' / ')} s · ${t.energy.toFixed(2)} MJ ES deployment</small>`;}
  }
  if(currentPhase==='rounddone'){$('#duel-next').disabled=busy||room.players[room.me].next;$('#next-ready-state').textContent=room.players[room.me].next?'Ready. Waiting for your friend.':'Both players must be ready to open the next brief.';}
 }
 function drawTrack(){
  const c=db.circuits.find(c=>c.id===room.brief.circuit),theta=({silverstone:99,monza:96,monaco:145,bahrain:93}[c.id])*Math.PI/180,xy=c.profile.x.map((x,i)=>[x*Math.cos(theta)-c.profile.y[i]*Math.sin(theta),-(x*Math.sin(theta)+c.profile.y[i]*Math.cos(theta))]);
  const xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),scale=Math.min(720/(maxx-minx),365/(maxy-miny));
  map=xy.map(([x,y])=>[(x-(minx+maxx)/2)*scale+450,(y-(miny+maxy)/2)*scale+250]);
  const points=[...map,map[0]].map(p=>p.join(',')).join(' '),[x,y]=map[0],q=map[2],angle=Math.atan2(q[1]-y,q[0]-x)*180/Math.PI;
  $('#duel-road').innerHTML=`<polyline class="duel-road-under" points="${points}" fill="none"/><polyline class="duel-road-line" points="${points}" fill="none"/><g class="finish-line" transform="translate(${x},${y}) rotate(${angle})"><path d="M0-17V17"/><text x="20" y="-20" transform="rotate(${-angle})">FINISH</text></g>`;
 }
 function animate(){
  if(!room?.race)return;const now=Date.now()+offset,t=Math.max(0,(now-room.startAt)/1000),durations=room.race.map(l=>l.time.at(-1)),first=Math.min(...durations),last=Math.max(...durations),count=Math.ceil((room.startAt-now)/1000);
  if(count>0){$('#race-countdown').hidden=false;$('#race-countdown').textContent=count;}else{$('#race-countdown').hidden=true;}
  $('#race-clock').textContent=formatLap(Math.min(t,last));
  const readings=room.race.map((lap,i)=>{
   const result={...lap,lapTime:durations[i]},sample=sampleAtTime(result,t),index=sample.index,next=(index+1)%lap.n,p=map[index],q=map[next],f=sample.fraction,angle=Math.atan2(q[1]-p[1],q[0]-p[0]),side=i===0?-3.5:3.5;
   const x=p[0]+(q[0]-p[0])*f-Math.sin(angle)*side,y=p[1]+(q[1]-p[1])*f+Math.cos(angle)*side;
   $(`#duel-car-${i}`).setAttribute('transform',`translate(${x},${y}) rotate(${angle*180/Math.PI})`);
   const finished=t>=durations[i];return `<div class="race-reading player-${i}"><span>${esc(room.players[i].name)}</span><b>${finished?'FINISHED':Math.round(lap.speed[index])+' <small>km/h</small>'}</b><p>${finished?formatLap(durations[i]):`Gear ${lap.gear[index]} · throttle ${lap.throttle[index].toFixed(0)}% · ERS ${lap.ers[index].toFixed(0)} kW`}</p><progress max="1" value="${clamp(sample.distance/(lap.n*lap.ds),0,1)}" aria-label="${esc(room.players[i].name)} lap progress"></progress></div>`;
  });if(now-lastReadoutAt>100){$('#race-telemetry').innerHTML=readings.join('');lastReadoutAt=now;}
  if(t>=first){const tie=Math.abs(durations[0]-durations[1])<.005,winner=durations[0]<durations[1]?0:1,announcement=$('#race-announcement');announcement.hidden=false;const finishKey=`${room.id}:${room.round}`;if(lastFinish!==finishKey){lastFinish=finishKey;announcement.textContent=tie?'Dead heat · shared round point':`${room.players[winner].name} crosses first.`;}}
  if(t>=last){request('status').catch(e=>alert(e.message,true));return;}
  if(!document.hidden)animation=requestAnimationFrame(animate);
 }
 document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAnimationFrame(animation);else if(room){renderRoom();if(room.race&&$('#duel-track-svg'))animate();}});
 const invited=new URL(location.href);if(invited.searchParams.has('room')&&invited.searchParams.has('invite')){$('#join-link').value=invited.href;alert('Invitation detected. Enter your name to join your friend.');}
 try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(saved&&typeof saved.token==='string'&&typeof saved.roomId==='string'){connection=saved;request('status').then(schedule).catch(e=>{connection=null;alert(e.message,true);});}}catch{}
 if(!ROOM_ENDPOINT)alert('Live rooms are not configured here yet. Offline lap experiments remain available.',true);
}
